<style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f4f7f9;color:#222}.header{background:#fff;border-bottom:1px solid #e1e6ea;padding:18px 24px;display:flex;align-items:center;justify-content:space-between;gap:15px}.header h1{margin:0;color:#123b5d;font-size:24px}.header span{color:#777;font-size:14px}.header-actions{display:flex;gap:10px}.container{width:100%;max-width:1150px;margin:0 auto;padding:25px 20px}.btn{border:none;border-radius:8px;padding:11px 16px;font-size:14px;font-weight:bold;cursor:pointer}.btn:disabled{opacity:.55;cursor:not-allowed}.btn-primary{background:#1976a8;color:#fff}.btn-secondary{background:#e8eef2;color:#234}.course-card,.card{background:#fff;border-radius:12px;box-shadow:0 4px 18px rgba(0,0,0,.06)}.course-card{padding:20px;margin-bottom:20px}.course-card h2{margin:0 0 15px;color:#123b5d}.course-info{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.info-item{background:#f7f9fa;border-radius:9px;padding:12px}.info-label{display:block;color:#777;font-size:12px;margin-bottom:5px}.info-value{font-weight:bold;color:#234}.top-bar{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:20px}.top-bar h3{margin:0;color:#123b5d;font-size:20px}.table-container{width:100%;overflow-x:auto}.card{overflow:hidden}table{width:100%;border-collapse:collapse}th{background:#f1f5f7;color:#456;font-size:13px;text-align:left;padding:13px;white-space:nowrap}td{padding:13px;border-top:1px solid #edf0f2;font-size:14px;vertical-align:top}.empty{text-align:center;padding:45px 20px;color:#777}.badge{display:inline-block;padding:5px 9px;border-radius:20px;font-size:12px;font-weight:bold}.badge-programado{background:#e7f1ff;color:#155b95}.badge-curso{background:#fff3d8;color:#956000}.badge-terminado{background:#e5f6ec;color:#18733b}.modal{display:none;position:fixed;inset:0;background:rgba(0,0,0,.45);align-items:center;justify-content:center;padding:20px;z-index:1000}.modal-box{width:100%;max-width:540px;background:#fff;border-radius:14px;padding:25px;max-height:90vh;overflow-y:auto}.modal-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.modal-header h3{margin:0;color:#123b5d}.close{border:none;background:transparent;font-size:25px;cursor:pointer;color:#777}.form-group{margin-bottom:16px}.form-group label{display:block;margin-bottom:7px;font-size:13px;font-weight:bold;color:#444}.form-group select,.form-group textarea{width:100%;padding:11px 12px;border:1px solid #d5dce1;border-radius:8px;font-size:15px;background:#fff}.form-group textarea{min-height:80px;resize:vertical}.link-nuevo{display:inline-block;margin-top:8px;color:#1976a8;text-decoration:none;font-size:13px;font-weight:bold}.form-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:20px}.message{display:none;padding:11px;border-radius:8px;margin-bottom:15px;font-size:14px}.message.error{background:#ffe8e8;color:#a52222}.message.success{background:#e5f6ec;color:#18733b}.historical-box{background:#fff8e8;border:1px solid #f1c45b;border-radius:12px;padding:14px;margin:0 0 16px}.historical-box strong{display:block;color:#7c4a03;margin-bottom:6px}.historical-box p{margin:0 0 12px;color:#72520d;line-height:1.4;font-size:13px}.checkline{display:flex;gap:9px;align-items:flex-start;margin-top:10px;font-size:13px;color:#55400c}.checkline input{margin-top:2px}.obs{max-width:330px;white-space:pre-wrap;color:#5c6670;font-size:12px}.admin-note{margin-top:12px;padding:10px 12px;border-radius:9px;background:#fff8e8;color:#72520d;font-size:13px;display:none}
@media(max-width:750px){.header{padding:15px;align-items:flex-start;flex-direction:column}.header-actions{width:100%;flex-direction:column}.header-actions .btn{width:100%}.container{padding:18px 12px}.course-info{grid-template-columns:1fr 1fr}.top-bar{align-items:stretch;flex-direction:column}.top-bar .btn{width:100%}.modal-box{padding:20px}}
</style>
</head>
<body>
<header class="header"><div><h1>Hache Natación</h1><span>Detalle de curso intensivo</span></div><div class="header-actions"><button class="btn btn-secondary" onclick="location.href='/intensivos.php'">Intensivos</button><button class="btn btn-secondary" onclick="location.href='/pagos.php'">Pagos</button></div></header>
<main class="container">
<div id="message" class="message"></div>
<div class="course-card"><h2>Curso intensivo</h2><div class="course-info"><div class="info-item"><span class="info-label">Inicio</span><span class="info-value" id="cursoInicio">-</span></div><div class="info-item"><span class="info-label">Fin</span><span class="info-value" id="cursoFin">-</span></div><div class="info-item"><span class="info-label">Precio</span><span class="info-value" id="cursoPrecio">-</span></div><div class="info-item"><span class="info-label">Estado</span><span class="info-value" id="cursoEstado">-</span></div></div><div id="adminClosedNote" class="admin-note"></div></div>
<div class="top-bar"><h3>Alumnos del curso</h3><button class="btn btn-primary" id="btnAgregar">+ Agregar alumno</button></div>
<div class="card"><div class="table-container"><table><thead><tr><th>Alumno</th><th>Horario</th><th>Reposiciones</th><th>Cancelaciones</th><th>Observaciones</th></tr></thead><tbody id="alumnosBody"><tr><td colspan="5" class="empty">Cargando alumnos...</td></tr></tbody></table></div></div>
</main>
<div class="modal" id="modalAlumno"><div class="modal-box"><div class="modal-header"><h3 id="modalTitle">Agregar alumno al intensivo</h3><button class="close" id="btnCerrar">×</button></div><div id="formMessage" class="message"></div><form id="formAlumno">
<div id="historicalBox" class="historical-box" hidden><strong>Corrección histórica de ADMIN</strong><p>La inscripción normal de este curso ya cerró. Puedes completar datos atrasados sin reabrir el curso ni cambiar las reglas para alumnos nuevos. El motivo quedará en el historial del alumno y en las observaciones del intensivo.</p><div class="form-group"><label for="motivo_correccion">Motivo de la corrección *</label><textarea id="motivo_correccion" maxlength="700" placeholder="Ej. Importación atrasada de Palapas: alumno pertenecía realmente al grupo del 17/08/2026."></textarea></div><label class="checkline"><input type="checkbox" id="sincronizar_fecha_inicio"><span>Ajustar también la fecha de inicio del alumno a la fecha de este curso. Úsalo solo si esa es la fecha correcta de su expediente.</span></label></div>
<div class="form-group"><label for="alumno_id">Alumno</label><select id="alumno_id" required><option value="">Seleccionar alumno...</option></select><a href="#" id="linkNuevoAlumno" class="link-nuevo">+ El alumno no está en la lista</a></div>
<div class="form-group"><label for="horario_id">Horario</label><select id="horario_id" required><option value="">Seleccionar horario...</option></select></div>
<div class="form-group"><label for="observaciones">Observaciones</label><textarea id="observaciones" maxlength="1000"></textarea></div>
<div class="form-actions"><button type="button" class="btn btn-secondary" id="btnCancelar">Cancelar</button><button type="submit" class="btn btn-primary" id="btnGuardar">Agregar alumno</button></div>
</form></div></div>
<script>
const ES_ADMIN=<?= $esAdmin?'true':'false' ?>;
const params=new URLSearchParams(location.search);const cursoId=params.get('id');const alumnoNuevoId=params.get('alumno_nuevo');
const alumnosBody=document.getElementById('alumnosBody');const alumnoSelect=document.getElementById('alumno_id');const horarioSelect=document.getElementById('horario_id');const modal=document.getElementById('modalAlumno');const form=document.getElementById('formAlumno');const message=document.getElementById('message');const formMessage=document.getElementById('formMessage');const linkNuevoAlumno=document.getElementById('linkNuevoAlumno');const historicalBox=document.getElementById('historicalBox');const motivoCorreccion=document.getElementById('motivo_correccion');const syncFecha=document.getElementById('sincronizar_fecha_inicio');const btnAgregar=document.getElementById('btnAgregar');const btnGuardar=document.getElementById('btnGuardar');const modalTitle=document.getElementById('modalTitle');const adminClosedNote=document.getElementById('adminClosedNote');let cursoActual=null;
function escaparHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function mostrarMensaje(el,texto,tipo){el.textContent=texto;el.className='message '+tipo;el.style.display='block'}function ocultarMensaje(el){el.style.display='none'}
function formatearPrecio(v){return Number(v||0).toLocaleString('es-MX',{style:'currency',currency:'MXN'})}function formatearHorario(i,f){return (i||'').substring(0,5)+' - '+(f||'').substring(0,5)}
function formatearEstado(e){if(e==='PROGRAMADO')return '<span class="badge badge-programado">Programado</span>';if(e==='EN_CURSO')return '<span class="badge badge-curso">En curso</span>';return '<span class="badge badge-terminado">Terminado</span>'}
if(cursoId)linkNuevoAlumno.href='/agregar-alumno.php?origen=intensivo&curso_id='+encodeURIComponent(cursoId);else linkNuevoAlumno.href='/agregar-alumno.php';
async function cargarCatalogoAlumnos(){const r=await fetch('/api/alumnos.php');const d=await r.json();if(!d.ok)throw new Error(d.error||'No se pudieron cargar los alumnos');alumnoSelect.innerHTML='<option value="">Seleccionar alumno...</option>';for(const a of(d.alumnos||[])){const o=document.createElement('option');o.value=a.id;o.textContent=a.nombre;alumnoSelect.appendChild(o)}if(alumnoNuevoId){alumnoSelect.value=alumnoNuevoId;abrirModal()}}
function configurarCorreccion(){const cerrada=cursoActual&&cursoActual.inscripcion_abierta===false;if(cerrada&&ES_ADMIN){historicalBox.hidden=false;modalTitle.textContent='Agregar alumno · corrección histórica';btnGuardar.textContent='Guardar corrección'}else{historicalBox.hidden=true;modalTitle.textContent='Agregar alumno al intensivo';btnGuardar.textContent='Agregar alumno';motivoCorreccion.value='';syncFecha.checked=false}}
function abrirModal(){form.reset();ocultarMensaje(formMessage);configurarCorreccion();if(alumnoNuevoId)alumnoSelect.value=alumnoNuevoId;modal.style.display='flex'}function cerrarModal(){modal.style.display='none'}
async function cargarCurso(){if(!cursoId){mostrarMensaje(message,'No se especificó el curso intensivo.','error');return}alumnosBody.innerHTML='<tr><td colspan="5" class="empty">Cargando alumnos...</td></tr>';try{const r=await fetch('/api/intensivo-alumnos.php?curso_id='+encodeURIComponent(cursoId));const d=await r.json();if(!d.ok)throw new Error(d.error||'No se pudo cargar el curso');cursoActual=d.curso;document.getElementById('cursoInicio').textContent=cursoActual.fecha_inicio||'-';document.getElementById('cursoFin').textContent=cursoActual.fecha_fin||'-';document.getElementById('cursoPrecio').textContent=formatearPrecio(cursoActual.precio);document.getElementById('cursoEstado').innerHTML=formatearEstado(cursoActual.estado);if(cursoActual.inscripcion_abierta===false){if(d.es_admin){adminClosedNote.style.display='block';adminClosedNote.textContent='La inscripción normal está cerrada. Como ADMIN puedes usar “Corrección histórica” para completar importaciones o datos atrasados; el motivo quedará auditado.';btnAgregar.disabled=false;btnAgregar.textContent='+ Corrección histórica'}else{adminClosedNote.style.display='block';adminClosedNote.textContent='La inscripción de este curso está cerrada. Solo un ADMIN puede registrar correcciones históricas.';btnAgregar.disabled=true;btnAgregar.textContent='Inscripción cerrada'}}else{adminClosedNote.style.display='none';btnAgregar.disabled=!d.es_admin;btnAgregar.textContent='+ Agregar alumno'}horarioSelect.innerHTML='<option value="">Seleccionar horario...</option>';for(const h of(d.horarios||[])){const o=document.createElement('option');o.value=h.id;o.textContent=formatearHorario(h.hora_inicio,h.hora_fin);horarioSelect.appendChild(o)}const alumnos=d.alumnos||[];if(!alumnos.length){alumnosBody.innerHTML='<tr><td colspan="5" class="empty">Este curso todavía no tiene alumnos.</td></tr>';return}alumnosBody.innerHTML='';for(const a of alumnos){const tr=document.createElement('tr');tr.innerHTML='<td>'+escaparHtml(a.alumno_nombre)+'</td><td>'+escaparHtml(formatearHorario(a.hora_inicio,a.hora_fin))+'</td><td>'+Number(a.reposiciones_justificadas||0)+'</td><td>'+Number(a.reposiciones_cancelacion||0)+'</td><td class="obs">'+escaparHtml(a.observaciones||'')+'</td>';alumnosBody.appendChild(tr)}}catch(e){console.error(e);mostrarMensaje(message,e.message||'Error al cargar el curso.','error')}}
btnAgregar.addEventListener('click',()=>{if(!btnAgregar.disabled)abrirModal()});document.getElementById('btnCerrar').addEventListener('click',cerrarModal);document.getElementById('btnCancelar').addEventListener('click',cerrarModal);modal.addEventListener('click',e=>{if(e.target===modal)cerrarModal()});
form.addEventListener('submit',async e=>{e.preventDefault();ocultarMensaje(formMessage);const historica=Boolean(cursoActual&&cursoActual.inscripcion_abierta===false);const datos={curso_intensivo_id:cursoId,alumno_id:alumnoSelect.value,horario_id:horarioSelect.value,observaciones:document.getElementById('observaciones').value.trim()||null,correccion_historica:historica,motivo_correccion:historica?motivoCorreccion.value.trim():null,sincronizar_fecha_inicio:historica?syncFecha.checked:false};if(!datos.curso_intensivo_id||!datos.alumno_id||!datos.horario_id){mostrarMensaje(formMessage,'Selecciona alumno y horario.','error');return}if(historica&&!datos.motivo_correccion){mostrarMensaje(formMessage,'Escribe el motivo de la corrección histórica.','error');motivoCorreccion.focus();return}try{btnGuardar.disabled=true;const r=await fetch('/api/intensivo-alumnos.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(datos)});const d=await r.json();if(!d.ok)throw new Error(d.error||'No se pudo agregar el alumno');cerrarModal();mostrarMensaje(message,d.correccion_historica?'Corrección histórica guardada y auditada.':'Alumno agregado al curso intensivo.','success');history.replaceState({},'','/intensivo-detalle.php?id='+encodeURIComponent(cursoId));await cargarCurso()}catch(err){mostrarMensaje(formMessage,err.message||'Error al agregar el alumno.','error')}finally{btnGuardar.disabled=false}});
Promise.all([cargarCurso(),cargarCatalogoAlumnos()]).catch(e=>{console.error(e);mostrarMensaje(message,e.message||'Error al cargar la información.','error')});
</script>
</body>
</html>
